    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="quiz-card" aria-labelledby="page-title">
        <h1 id="page-title">Computer Languages Quiz</h1>
        <p class="intro">
          Choose every answer that applies for each question, then check your score.
        </p>

        <form id="quiz-form">
          <div class="form-field">
            <fieldset aria-describedby="q1-help">
              <legend>1. Which of these are programming languages?</legend>
              <p class="help-text" id="q1-help">
                Select all options that are commonly used to write software.
              </p>
              <div class="choices">
                <label class="choice" for="q1-python">
                  <input id="q1-python" name="q1" type="checkbox" value="python" data-correct="true">
                  Python
                </label>
                <label class="choice" for="q1-html">
                  <input id="q1-html" name="q1" type="checkbox" value="html">
                  HTML
                </label>
                <label class="choice" for="q1-java">
                  <input id="q1-java" name="q1" type="checkbox" value="java" data-correct="true">
                  Java
                </label>
                <label class="choice" for="q1-css">
                  <input id="q1-css" name="q1" type="checkbox" value="css">
                  CSS
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>2. Which languages are often used for web development?</legend>
              <div class="choices">
                <label class="choice" for="q2-js">
                  <input id="q2-js" name="q2" type="checkbox" value="javascript" data-correct="true">
                  JavaScript
                </label>
                <label class="choice" for="q2-ruby">
                  <input id="q2-ruby" name="q2" type="checkbox" value="ruby" data-correct="true">
                  Ruby
                </label>
                <label class="choice" for="q2-swift">
                  <input id="q2-swift" name="q2" type="checkbox" value="swift">
                  Swift
                </label>
                <label class="choice" for="q2-php">
                  <input id="q2-php" name="q2" type="checkbox" value="php" data-correct="true">
                  PHP
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>3. Which languages are statically typed by default?</legend>
              <div class="choices">
                <label class="choice" for="q3-csharp">
                  <input id="q3-csharp" name="q3" type="checkbox" value="csharp" data-correct="true">
                  C#
                </label>
                <label class="choice" for="q3-go">
                  <input id="q3-go" name="q3" type="checkbox" value="go" data-correct="true">
                  Go
                </label>
                <label class="choice" for="q3-python">
                  <input id="q3-python" name="q3" type="checkbox" value="python">
                  Python
                </label>
                <label class="choice" for="q3-rust">
                  <input id="q3-rust" name="q3" type="checkbox" value="rust" data-correct="true">
                  Rust
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Check answers</button>
            <p class="result" id="quiz-result" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>

    <script>
      const quizForm = document.querySelector("#quiz-form");
      const result = document.querySelector("#quiz-result");
      const questionNames = ["q1", "q2", "q3"];

      function isQuestionCorrect(questionName) {
        const answers = [...quizForm.querySelectorAll(`input[name="${questionName}"]`)];

        return answers.every((answer) => answer.checked === (answer.dataset.correct === "true"));
      }

      quizForm.addEventListener("submit", (event) => {
        event.preventDefault();

        const correctCount = questionNames.filter(isQuestionCorrect).length;
        const plural = correctCount === 1 ? "question" : "questions";

        result.textContent = `You answered ${correctCount} of ${questionNames.length} ${plural} correctly.`;
      });
    </script>
